WFJ.Data.add("spell", {
  [401417] = { "$D1かけて体力を$N1回復し、$D2の間Temporal Beaconを付与します。\n\nTemporal Beacon\n$I1\n対象の時空間の位置を記録します。術者が与えたArcaneダメージの$N4%が、術者の現在のTemporal Beaconの対象それぞれへのクロノマンシーの治療に変換されます。この治療は自分に対しては$N5%減少し、複数の対象にダメージを与えるArcane呪文によるダメージの場合はさらに$N6%減少します。", { "$D1かけて体力を$N1回復しています。移動速度が$N3%上昇しています。", "$D1かけて体力を$N1回復しています。", shape = { "3/1", "2/1" } }, 0x7470eeff, 0x931e594a, "uu" },
  [401460] = { "$D1かけて対象の体力を$N1回復し、$D2の間Temporal Beaconを付与します。\n\n$I1\n対象の時空上の位置を記録します。術者が与えるすべてのArcaneダメージの$N4%が、術者の現在のTemporal Beaconの対象それぞれへの時間術の治癒に変換されます。この治癒は自分自身に対しては$N5%減少し、複数の対象にダメージを与えるArcane呪文によるダメージの場合はさらに$N6%減少します。", "$D1かけて体力を$N1回復しています。", 0x5178d77e, 0x71292dfd, "uu" },
  [401462] = { "Temporal Beaconがかかっている現在の対象は、直前$N1秒間に受けたすべてのダメージを即座に回復します。$N2秒前にTemporal Beaconがかかっていなかった対象には効果がありません。", nil, 0x490806a3, nil, "um" },
  [401488] = { "脚部にShadowstrikeのルーンを刻みます：\n\n$I1\n対象の背後にテレポートして攻撃し、対象に$N1%の武器ダメージを与えます。ステルス状態である必要があります。コンボポイントを$N2獲得します。", nil, 0x2b51ff0b, nil, "um" },
  [401502] = { "敵にフロストファイアの矢を放ち、$N1のFrostfireダメージを与え、移動速度を$N2%低下させ、さらに$D1かけて$N3のFrostfireダメージを与えます。この呪文は対象のFrostとFireの耐性のうち低いほうで判定され、FrostとFireの両方のダメージとして扱われます。", "移動速度が$N1%低下しています。$N3秒ごとに$N2のFrostfireダメージを受けます。", 0xff979685, 0x3991e2af, "uu" },
  [401556] = { "対象に向かって進むspellfireの炎を呼び出し、spellfireの跡を残します。この跡は周囲の敵に毎秒$N1のSpellfireダメージを与えます。効果時間は$D1です。", nil, 0xb96c469d, nil, "um" },
  [401558] = { "$N2秒ごとに$N1のFireダメージを与えます。", "$N2秒ごとに$N1のFireダメージを与えます。", 0x5c2b23fa, 0xe0649799, "uu" },
  [401617] = { "印のついた場所で宝を掘り出します", nil, 0xcb9fbb49, nil, "um" },
  [401681] = { "Comphrehension Primerで呪文のメモを解読し、新しいEngraving呪文を習得します。", nil, 0x1278ff25, nil, "um" },
  [401683] = { "呪文のメモを解読して、新しいルーン彫刻のレシピにしようと試みます。", nil, 0x68ecd2ae, nil, "um" },
  [401684] = { "呪文のメモを解読して、新しいルーン彫刻のレシピにしようと試みます。", nil, 0x68ecd2ae, nil, "um" },
  [401699] = { "Azora Apprentice Notesを8枚組み合わせて、新しいルーン彫刻のレシピを見つけます。", nil, 0x0d2429ee, nil, "um" },
  [401719] = { "Arcane Barrageのアビリティを得ます：\n\n$I1\n敵の対象に複数のミサイルを放ち、$N1のArcaneダメージを与えます。この呪文には$N2%の確率でMissile Barrageを発動させる効果もあります。", nil, 0x5cc6b146, nil, "um" },
  [401722] = { "外套にArcane Barrageのルーンを刻みます：\n\n$I1\n敵の対象に複数のミサイルを放ち、$N1のArcaneダメージを与えます。この呪文には$N2%の確率でMissile Barrageを発動させる効果もあります。", nil, 0x948d9b5e, nil, "um" },
  [401724] = { "Hot Streakのアビリティを得ます：\n\n$I1\nFireball、Frostfire Bolt、Fire Blast、Scorchによる非周期のクリティカルヒットが、$D1以内に詠唱する次のPyroblastの詠唱時間を$N2%短縮します。最大$N3回までスタックします。", nil, 0x03e95487, nil, "um" },
  [401725] = { "Brain Freezeのアビリティを得ます：\n\n$I1\n冷却効果のあるFrostダメージ呪文に、次のFireball、Spellfrost Bolt、Balefire Bolt、Frostfire Boltのいずれかの呪文を即時詠唱かつマナ消費なしにする確率が$N1%付与されます。", nil, 0x7ed1f1da, nil, "um" },
  [401726] = { "Advanced Wardingのアビリティを得ます：\n\n$I1\nMana Shield、Frost Ward、Fire Wardの呪文を味方のどの対象にも詠唱できるようになり、吸収するダメージが$N1%増加します。またMana Shieldが吸収ダメージあたりに消費するマナが$N2%減少します。さらに、Remove Lesser CurseがRemove Greater Curseに置き換わります。\n\n$I2\n味方の対象からCurseを$N3個、有害なMagic効果を$N4個取り除きます。", nil, 0x3b37264b, nil, "um" },
  [401729] = { "Arcane Blastのアビリティを得ます：\n\n$I1\n対象にエネルギーを叩きつけ、$N1のArcaneダメージを与えます。Arcane Blastを詠唱するたびに、他のすべての呪文のダメージが$N2%増加し、Arcane Blastのマナコストが$N3%増加します。効果は最大$N4回までスタックし、$D1、または他のダメージ呪文を詠唱するまで持続します。", nil, 0x6a8d4cac, nil, "um" },
  [401731] = { "Living Bombのアビリティを得ます：\n\n$I1\n対象がLiving Bombとなり、$D1かけて$N1のFireダメージを受けます。$D2後、または呪文が解除されたとき、対象は爆発し、$N5ヤード以内のすべての敵に$N4のFireダメージを与えます。\n\nLiving Bombは、Scorchから発動する、またはScorchを強化するすべての才能と効果の恩恵を受けます。", nil, 0x395d18dc, nil, "um" },
  [401732] = { "Ice Lanceのアビリティを得ます：\n\n$I1\n敵の対象に$N1のFrostダメージを与えます。Frozen状態の対象には$N2%増加したダメージを与えます。", nil, 0xee304a05, nil, "um" },
  [401734] = { "Rewind Timeのアビリティを得ます：\n\n$I1\nTemporal Beaconが付与されている現在の対象は、直前$N1秒間に受けたすべてのダメージを即座に回復します。$N2秒前にTemporal Beaconが付与されていなかった対象には効果がありません。", nil, 0x6a873727, nil, "um" },
  [401735] = { "Frostfire Boltのアビリティを得ます：\n\n$I1\n敵にフロストファイアの矢を放ち、$N1のFrostfireダメージを与え、移動速度を$N2%低下させ、$D1かけてさらに$N3のFrostfireダメージを与えます。この呪文は対象のFrostとFireの耐性のうち低い方で判定され、FrostダメージとFireダメージの両方として扱われます。", nil, 0x3a219dc9, nil, "um" },
  [401736] = { "Missile Barrageのアビリティを得ます：\n\n$I1\nArcane Blastの呪文に$N1%の確率、Fireball、Frostbolt、Frostfire Boltの呪文に$N2%の確率で、次のArcane Missilesのチャネリング時間を$N3%短縮し、マナコストを$N4%減少させ、ミサイルが$D1ごとに発射されるようにする効果を与えます。", nil, 0x967fe765, nil, "um" },
  [401737] = { "Overheatのアビリティを得ます：\n\n$I1\nFire Blastが常にクリティカルになり、他の呪文の詠唱中にも詠唱でき、グローバルクールダウンの影響を受けなくなりますが、クールダウンが$D1に延長されます。", nil, 0x921647ac, nil, "um" },
  [401741] = { "Fingers of Frostのアビリティを得ます：\n\n$I1\nChill効果に、$N1%の確率でFingers of Frostの効果を得る力を与えます。この効果により、次に詠唱する$N2回の呪文は対象がFrozenであるものとして扱われます。$D1持続します。", nil, 0xa7da2ad2, nil, "um" },
  [401743] = { "Regenerationのアビリティを得ます：\n\n$I1\n$D1かけて対象の体力を$N1回復し、$D2の間Temporal Beaconを付与します。\n\nTemporal Beacon\n$I2\n対象の時空上の位置を記録します。術者が与えるすべてのArcaneダメージの$N4%が、術者の現在のTemporal Beaconの対象それぞれへの時間術の治癒に変換されます。この治癒は自分自身に対しては$N5%減少し、複数の対象にダメージを与えるArcane呪文によるダメージの場合はさらに$N6%減少します。", nil, 0x24c8a9d0, nil, "um" },
  [401744] = { "Living Flameのアビリティを得ます：\n\n$I1\n対象に向かって進む呪炎の炎を召喚し、呪炎の跡を残します。この跡は近くの敵に毎秒$N1のSpellfireダメージを与えます。$D1持続します。", nil, 0x8e90ef6f, nil, "um" },
  [401749] = { "兜にHot Streakのルーンを刻みます：\n\n$I1\nFireball、Frostfire Bolt、Fire Blast、Scorchによる非周期的なクリティカルで、$D1以内に詠唱する次のPyroblastの詠唱時間が$N2%短縮されます。最大$N3回まで累積します。", nil, 0xcad31fdf, nil, "um" },
  [401752] = { "ブーツにBrain Freezeのルーンを刻みます：\n\n$I1\n冷却効果を持つFrostダメージ呪文に、$N1%の確率で次のFireball、Spellfrost Bolt、Balefire Bolt、Frostfire Boltを即時詠唱にし、マナを消費しなくする効果が付きます。", nil, 0x90851280, nil, "um" },
  [401754] = { "兜にAdvanced Wardingのルーンを刻みます：\n\n$I1\nMana Shield、Frost Ward、Fire Wardを任意の味方の対象に使えるようになり、吸収するダメージが$N1%増加します。またMana Shieldは吸収したダメージあたりのマナ消費が$N2%減少します。さらに、Remove Lesser CurseがRemove Greater Curseに置き換わります。\n\n$I2\n味方の対象からCurseを$N3個、有害なMagic効果を$N4個取り除きます。", nil, 0xae017b08, nil, "um" },
  [401757] = { "手袋にArcane Blastのルーンを刻みます：\n\n$I1\n対象にエネルギーを叩きつけ、$N1のArcaneダメージを与えます。Arcane Blastを詠唱するたびに、他のすべての呪文のダメージが$N2%増加し、Arcane Blastのマナ消費が$N3%増加します。効果は最大$N4回まで累積し、$D1の間、または他のダメージ呪文を詠唱するまで持続します。", nil, 0x8e71b319, nil, "um" },
  [401759] = { "胸部にBurnoutのルーンを刻みます：\n\n$I1\nすべての呪文のクリティカル率が$N1%上昇しますが、非周期の呪文のクリティカルで基本マナの$N2%が追加で消費されるようになります。", nil, 0x32623dd4, nil, "um" },
  [401760] = { "手袋にIce Lanceのルーンを刻みます：\n\n$I1\n敵の対象に$N1のFrostダメージを与えます。Frozen状態の対象には$N2%増加したダメージを与えます。", nil, 0x38968448, nil, "um" },
  [401761] = { "腕甲にRewind Timeのルーンを刻みます：\n\n$I1\n自分のTemporal Beaconが付いている現在の対象が、直近$N1秒間に受けたすべてのダメージを即座に回復します。$N2秒前にTemporal Beaconが付いていなかった対象には効果がありません。", nil, 0x5aca7557, nil, "um" },
  [401762] = { "ベルトにFrostfire Boltのルーンを刻みます：\n\n$I1\n敵にフロストファイアの矢を放ち、$N1のFrostfireダメージを与え、移動速度を$N2%低下させ、さらに$D1かけて$N3のFrostfireダメージを与えます。この呪文は対象のFrostとFireの耐性のうち低い方で判定され、FrostとFire両方のダメージとして扱われます。", nil, 0x699fda74, nil, "um" },
  [401763] = { "ベルトにMissile Barrageのルーンを刻みます：\n\n$I1\nArcane Blastに$N1%、Fireball、Frostbolt、Frostfire Boltに$N2%の確率で、次のArcane Missilesのチャネリング時間を$N3%短縮し、マナ消費を$N4%減らし、ミサイルが$D1ごとに発射されるようにする効果を付与します。", nil, 0x90adccfe, nil, "um" },
  [401764] = { "外套にOverheatのルーンを刻みます：\n\n$I1\nFire Blastは必ずクリティカルになり、他の呪文の詠唱中にも使用でき、グローバルクールダウンの影響を受けませんが、クールダウンが$D1に増加します。", nil, 0x8ba49575, nil, "um" },
  [401765] = { "胸部か法衣にFingers of Frostのルーンを刻みます：\n\n$I1\nChill効果に$N1%の確率でFingers of Frost効果を得る効果が付きます。Fingers of Frostは、次に詠唱する$N2回の呪文を対象がFrozen状態であるかのように扱います。$D1持続します。", nil, 0xccde94fb, nil, "um" },
  [401767] = { "胸部か法衣にRegenerationのルーンを刻みます：\n\n$I1\n$D1かけて体力を$N1回復し、$D2の間Temporal Beaconを付与します。\n\nTemporal Beacon\n$I2\n対象の時空間の位置を記録します。術者が与えたArcaneダメージの$N4%が、術者の現在のTemporal Beaconの対象それぞれへのクロノマンシーの治療に変換されます。この治療は自分に対しては$N5%減少し、複数の対象にダメージを与えるArcane呪文によるダメージの場合はさらに$N6%減少します。", nil, 0xf111a62e, nil, "um" },
  [401768] = { "脚部にLiving Flameのルーンを刻みます：\n\n$I1\n対象に向かって移動するスペルファイアの炎を召喚し、スペルファイアの跡を残します。この跡は近くの敵に毎秒$N1のSpellfireダメージを与えます。$D1持続します。", nil, 0x4d4c79bc, nil, "um" },
  [401847] = { "他の$N1枚の断片と組み合わせて、完全な地図を作ります。", nil, 0xdcc7f5cf, nil, "um" },
  [401859] = { "対象に呪文をかけ、次にダメージを受けるか周期的でない回復を受けたときに$N1回復させます。回復が発生すると、Prayer of Mendingは$N2ヤード以内のパーティまたはレイドのメンバーに移ります。最大$N3回移り、移るたびに$D1持続します。この呪文は、術者ごとに一度に1体の対象にしかかけられません。", nil, 0x18d9951a, nil, "um" },
  [401863] = { "対象に呪文をかけ、次にダメージを受けたときに回復させます。回復が発生すると、Prayer of Mendingは$N1ヤード以内のパーティまたはレイドのメンバーに飛び移ります。最大$N2回飛び移り、飛び移るたびに$D1持続します。この呪文は一度に一体の対象にしかかけられません。", nil, 0x5562ca1a, nil, "um" },
  [401877] = { "対象に呪文をかけ、次にダメージを受けるか治癒を受けたときに対象を回復させます。回復が発生すると、Prayer of Mendingは$N1ヤード以内のパーティーまたはレイドのメンバーに飛び移ります。最大$N2回まで飛び移り、飛び移るたびに$D1持続します。この呪文は一度に一つの対象にしかかけられません。", "ダメージを受けたときや回復を受けたときに回復します。", 0x5aeb0cdd, 0xa73e48f0, "uu" },
  [401937] = { "友好的な対象と術者を$N1回復します。脅威は低めです。", nil, 0xda5be047, nil, "um" },
  [401946] = { "対象プレイヤーから$N1ヤード以内にいる、そのプレイヤーのパーティメンバー全員を$N2回復します。", nil, 0x4267c87c, nil, "um" },
  [401955] = { "闇の束縛の言葉で、対象に$N1のShadowダメージを与えます。Shadow Word: Deathで対象を倒せなかった場合、術者は対象に与えようとしたダメージの$N2%に等しいダメージを受けます。", nil, 0x51a0e84b, nil, "um" },
  [401956] = { nil, "すぐに再生する氷塊に閉じ込められています。", nil, 0xeedfae42, "mu" },
  [401962] = { "闇の束縛の言葉で、対象にShadowダメージを与えます。Shadow Word: Deathで対象を倒せなかった場合、術者は対象に与えたダメージと同じだけのダメージを受けます。", nil, 0xdc462015, nil, "um" },
  [401969] = { "Shadow Word: Painが、$N2ヤード以内の近くにいる追加の対象最大$N1体にも効果を及ぼすようになります。", nil, 0xa6764800, nil, "um" },
  [401977] = { "影の悪鬼を作り出して対象を攻撃させます。Shadowfiendが攻撃すると、術者はマナを$N1%得ます。効果時間は$D1です。", nil, 0x609469be, nil, "um" },
  [401981] = { nil, "まだ熱さが足りない！もっと熱を！", nil, 0x9987dc33, "mu" },
  [401984] = { "Shadowfiendの近接攻撃が対象からエネルギーを吸い取り、主人のマナに変換します。", "Shadowダメージをマナに変換します。", 0x63a87b32, 0x41ef7edc, "uu" },
  [401988] = { "Shadowfiendの近接攻撃が対象からエネルギーを吸い取り、主人のマナに変換します。", nil, 0x63a87b32, nil, "um" },
  [401990] = { "影の中を這って敵の対象に近づき、$D1の間、Shadowfiendの与えるダメージを$N1%増加させます。", "ダメージが$N1%増加します。", 0x9c462814, 0xb557266a, "uu" },
